{
  "identity": {
    "name": "IT Secure LLC",
    "location": "Meridian, Idaho",
    "claims": [
      {
        "statement": "IT Secure LLC is an IT services provider based in Meridian, Idaho, serving the Treasure Valley region.",
        "label": "fact",
        "sourceUrl": "https://itsecure.tech/",
        "quote": "Based in Meridian, we provide fast, reliable IT support to businesses throughout Boise, Nampa, Eagle, and the Treasure Valley."
      },
      {
        "statement": "The company maintains a physical mailing address in Meridian, Idaho.",
        "label": "fact",
        "sourceUrl": "https://itsecure.tech/privacy-policy/",
        "quote": "IT Secure LLC Data Protection Officer 148 E Cordoba Ct Meridian, ID 83646 United States"
      }
    ]
  },
  "industry": {
    "industry": "Information Technology Services / Managed Service Provider (MSP)",
    "activities": [
      "Managed IT support and remote monitoring",
      "Cybersecurity and threat protection",
      "Compliance and security assessments",
      "Business network management",
      "Data backup and disaster recovery",
      "Cloud managed services",
      "Apple and Microsoft environment support",
      "Business VoIP telecommunications"
    ],
    "claims": [
      {
        "statement": "IT Secure operates as a managed service provider offering managed IT support, cybersecurity, and platform support.",
        "label": "fact",
        "sourceUrl": "https://itsecure.tech/",
        "quote": "We offer proactive managed IT support, industry-leading cybersecurity, and expert assistance for both Apple and Microsoft environments—covering all your business technology needs in one place."
      },
      {
        "statement": "IT Secure provides network management, data backup, cloud infrastructure management, and VoIP solutions.",
        "label": "fact",
        "sourceUrl": "https://itsecure.tech/services/",
        "quote": "Managed IT Support Continuous monitoring and management of your IT infrastructure to ensure optimal performance and quick resolution of issues."
      },
      {
        "statement": "IT Secure LLC does not operate in the home-services contracting trades such as HVAC, plumbing, or electrical.",
        "label": "inference",
        "sourceUrl": "https://itsecure.tech/services/",
        "quote": null
      }
    ]
  },
  "publicInformation": {
    "officialWebsite": "https://itsecure.tech/",
    "claims": [
      {
        "statement": "The company operates its primary web presence at itsecure.tech.",
        "label": "fact",
        "sourceUrl": "https://itsecure.tech/",
        "quote": "IT Secure | Treasure Valley's Trusted Managed Service Provider WE HANDLE THE TECH. YOU HANDLE THE BUSINESS."
      },
      {
        "statement": "IT Secure highlights its technology industry partnerships with Microsoft, Apple, and Google.",
        "label": "fact",
        "sourceUrl": "https://itsecure.tech/partnerships/",
        "quote": "Partnerships with leading technology companies are integral to the success of a Managed Service Provider (MSP) that deliver outsourced IT services to businesses."
      }
    ]
  },
  "licensing": {
    "claims": [
      {
        "statement": "The business operates under the formal legal entity name IT Secure LLC.",
        "label": "fact",
        "sourceUrl": "https://itsecure.tech/privacy-policy/",
        "quote": "This privacy notice for IT Secure LLC (doing business as IT Secure) (\"we,\" \"us,\" or \"our\"), describes how and why we might collect"
      },
      {
        "statement": "The company is organized as a limited liability company in the state of Idaho.",
        "label": "inference",
        "sourceUrl": "https://itsecure.tech/privacy-policy/",
        "quote": null
      }
    ],
    "limitations": "State business registration numbers, contractor licenses, or municipal trade licenses are not displayed on the website."
  },
  "existingSoftware": [
    {
      "product": "WePay",
      "purpose": "Payment processing for customer purchases and service transactions",
      "evidence": {
        "statement": "Payment handling and storage are managed by third-party processor WePay.",
        "label": "fact",
        "sourceUrl": "https://itsecure.tech/privacy-policy/",
        "quote": "All payment data is handled and stored by WePay."
      }
    },
    {
      "product": "Mosyle & Microsoft Intune",
      "purpose": "Mobile Device Management (MDM) platforms for managing client hardware fleets",
      "evidence": {
        "statement": "The company deploys and manages MDM software solutions including Mosyle and Microsoft Intune.",
        "label": "fact",
        "sourceUrl": "https://itsecure.tech/partnerships/apple-technical-partner/",
        "quote": "We implement and manage leading MDM platforms, including Mosyle and Microsoft Intune, enabling centralised control over every device in your organisation."
      }
    },
    {
      "product": "Calendly",
      "purpose": "Online appointment scheduling for consultations",
      "evidence": {
        "statement": "IT Secure incorporates Calendly widget scripts to facilitate online meeting bookings.",
        "label": "inference",
        "sourceUrl": "https://itsecure.tech/schedule-a-meeting/",
        "quote": null
      }
    },
    {
      "product": "Forminator",
      "purpose": "Web form capture for inbound contact inquiries",
      "evidence": {
        "statement": "The website employs the Forminator WordPress plugin to handle contact form submissions.",
        "label": "inference",
        "sourceUrl": "https://itsecure.tech/contact/",
        "quote": null
      }
    }
  ],
  "opportunityEvidence": [
    {
      "statement": "The company maintains online scheduling and digital form intake for prospective client inquiries.",
      "label": "fact",
      "sourceUrl": "https://itsecure.tech/contact/",
      "quote": "Phone [redacted] Email [email protected] TEXT SUPPORT Text \"SECURE\" to [redacted]"
    },
    {
      "statement": "The website's published navigation link to pricing is broken and returns an HTTP 404 not-found status.",
      "label": "inference",
      "sourceUrl": "https://itsecure.tech/",
      "quote": null
    }
  ],
  "problems": [
    {
      "problem": "Target segment mismatch: the company is an IT managed service provider rather than a home-services trade contractor.",
      "label": "inference",
      "basis": "IT Secure LLC offers managed IT, cybersecurity, network administration, and cloud services to businesses, placing it outside ForgeX's target market of owner-led residential HVAC, plumbing, and electrical contractors."
    },
    {
      "problem": "Broken pricing page link on public website.",
      "label": "inference",
      "basis": "The link https://itsecure.tech/pricing/ included in the primary website navigation bar and footer returns a 404 not-found error."
    }
  ],
  "existingSolutions": [
    {
      "solution": "WordPress Menu Management",
      "addresses": "Broken pricing link by either unlinking the navigation item or redirecting it until content is live.",
      "alreadyOwned": true
    },
    {
      "solution": "Calendly and Forminator",
      "addresses": "Lead booking and inbound web inquiries.",
      "alreadyOwned": true
    }
  ],
  "forgexSolutions": [],
  "feasibility": {
    "rating": "not applicable",
    "explanation": "No ForgeX solutions are applicable because IT Secure LLC operates in commercial IT services and cybersecurity rather than residential home services."
  },
  "aiDelivery": {
    "rating": "not applicable",
    "explanation": "Custom ForgeX AI agents are not recommended as the company is outside ForgeX's target market segment and already offers its own IT, cloud, and AI solutions."
  },
  "humanReview": [
    "No ForgeX workflow implementations are planned or proposed."
  ],
  "risks": [
    {
      "type": "operational",
      "description": "Engaging businesses outside the core home-service contractor segment wastes business development resources on companies that do not use field-service software or pay for residential job leads."
    }
  ],
  "commercial": {
    "supportable": false,
    "value": null,
    "implementationCost": null,
    "assumptions": [
      "No pricing figures are published on the website (the pricing page returns 404 not-found).",
      "Commercial value calculation is omitted because the company is outside ForgeX's segment."
    ]
  },
  "contacts": {
    "decisionMakerRoles": [
      "Owner",
      "Managing Member",
      "Chief Executive Officer"
    ],
