    "sourcesUsed": [
      {
        "url": "https://itsecure.tech/",
        "usedFor": "Business identity, location, core service offerings, and navigation structure"
      },
      {
        "url": "https://itsecure.tech/about/",
        "usedFor": "Company background, service description, and operating philosophy"
      },
      {
        "url": "https://itsecure.tech/contact/",
        "usedFor": "Contact channels, phone numbers, text support, and form implementation"
      },
      {
        "url": "https://itsecure.tech/pricing/",
        "usedFor": "Verification of pricing availability (returned HTTP 404)"
      },
      {
        "url": "https://itsecure.tech/services/",
        "usedFor": "Detailed listing of commercial IT and cloud service capabilities"
      },
      {
        "url": "https://itsecure.tech/partnerships/",
        "usedFor": "Technology vendor partnership details (Microsoft, Apple, Google)"
      },
      {
        "url": "https://itsecure.tech/privacy-policy/",
        "usedFor": "Legal entity name, physical postal address, DPO phone, and payment processor details"
      },
      {
        "url": "https://itsecure.tech/schedule-a-meeting/",
