      },
      {
        "url": "https://itsecure.tech/partnerships/apple-technical-partner/",
        "usedFor": "Mobile Device Management tool usage (Mosyle, Microsoft Intune)"
      },
      {
        "url": "https://itsecure.tech/services/managed-it/",
        "usedFor": "Managed IT operational scope and client problem profile"
      }
    ],
    "limitations": [
      "No specific owner or executive management profiles are published on non-testimonial website pages.",
      "The pricing page is unavailable (HTTP 404), leaving exact service rates unstated.",
      "Total employee headcount cannot be directly verified from the public website text."
    ]
  },
  "qualification": {
    "category": "not a fit",
    "rationale": "IT Secure LLC is a managed service provider (MSP) offering business IT infrastructure support, cybersecurity, cloud administration, and MDM solutions in Meridian, Idaho. It is not an owner-led home-service contractor in the HVAC, plumbing, or electrical trades. Because it falls outside ForgeX's target industry segment and provides its own technology and automation consulting services, it is qualified as 'not a fit'."
  }
}
